package com.knowflow.learning.adaptive;
import com.fasterxml.jackson.databind.*;import com.knowflow.entity.Task;import com.knowflow.exception.BusinessException;import com.knowflow.learning.actions.*;import com.knowflow.learning.actions.PlanModels.*;import com.knowflow.mapper.TaskMapper;import com.knowflow.service.TaskService;import com.knowflow.dto.TaskDTO;import lombok.RequiredArgsConstructor;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Component;import java.time.*;import java.util.*;import java.util.function.*;
/** Constraint adapter for the original daily draft/confirmation service, not a second task or plan store. */
@Component @RequiredArgsConstructor @ConditionalOnProperty(name="knowflow.product.adaptive-learning.enabled",havingValue="true")
public class SmartPlanSupport {
 private final ObjectMapper json;private final LearningContextService context;private final TaskMapper tasks;private final TaskService taskService;private final LearningWriteGuard guard;private final PlanClock clock;private final JdbcTemplate sql;
 @org.springframework.beans.factory.annotation.Autowired(required=false)private AdaptivePathService adaptive;
 public record Changes(List<Item> items,List<TaskChange> changes,List<String> warnings){}
 private JsonNode meta(Task t){try{return t.getLearningMetadata()==null?json.createObjectNode():json.readTree(t.getLearningMetadata());}catch(Exception e){throw new BusinessException(500,"任务学习元数据损坏，未调整");}}
 public boolean locked(Task t){return meta(t).path("planningLocked").asBoolean(false);}
 public int minutes(Task t,Item item){if(item!=null&&item.estimatedMinutes()>0&&item.estimatedMinutes()<=720)return item.estimatedMinutes();if(t.getStartTime()!=null&&t.getEndTime()!=null){long value=Duration.between(t.getStartTime(),t.getEndTime()).toMinutes();if(value>0&&value<=720)return (int)value;}return 30;}
 private boolean protectedTask(Task t,Request r){return locked(t)||t.getStartTime()!=null||t.getDueDate()!=null&&!t.getDueDate().isAfter(r.getDate());}
 public Changes build(long user,Request r,List<Task> owned,Function<Task,Item> metadata,Function<Task,String> priority){
  if(!r.getDate().equals(clock.now().atZone(LearningContextService.zone(r.getZoneId())).toLocalDate()))throw new BusinessException(400,"首批智能重排仅调整服务端今日计划");if(owned.isEmpty())throw new BusinessException(409,"今天没有可调整的未完成任务");if(owned.size()>20)throw new BusinessException(409,"首批一次最多调整20项任务");
  Set<Long> ids=new HashSet<>();owned.forEach(t->ids.add(t.getId()));if(!ids.containsAll(r.getTaskMinutes().keySet()))throw new BusinessException(400,"时长设置包含不属于今日待办的任务");
  var rank=new HashMap<Long,Integer>();var reasons=new HashMap<Long,String>();if(r.getPathId()!=null){if(adaptive==null)throw new BusinessException(409,"当前配置未启用路径建议");int index=0;for(var f:adaptive.facts(user,r.getPathId())){if(f.get("knowledgeId") instanceof Number n){rank.putIfAbsent(n.longValue(),index++);reasons.put(n.longValue(),f.get("reason").toString());}}}
  else{for(var c:context.read(user,r).candidates())if(c.knowledgeId()!=null){rank.merge(c.knowledgeId(),c.rank(),Math::min);reasons.putIfAbsent(c.knowledgeId(),c.reason());}}
  var costs=new HashMap<Long,Integer>();var pinned=new ArrayList<Task>();var optional=new ArrayList<Task>();var warnings=new ArrayList<String>();
  for(var t:owned){var old=metadata.apply(t);if(old!=null)context.validateResource(old,user);int oldMinutes=minutes(t,old),requested=r.getTaskMinutes().getOrDefault(t.getId(),oldMinutes);boolean fixed=protectedTask(t,r);if(fixed&&requested!=oldMinutes)throw new BusinessException(409,"锁定、定时或到期任务不能自动缩短");costs.put(t.getId(),requested);if(fixed)pinned.add(t);else optional.add(t);if(old==null)warnings.add("任务 #"+t.getId()+" 没有原时长，使用可编辑的30分钟估计，不代表真实用时");}
  int mandatory=pinned.stream().mapToInt(t->costs.get(t.getId())).sum();if(mandatory>r.getAvailableMinutes())throw new BusinessException(409,"锁定、定时或到期任务已超过可用时间；请调整预算，未移动这些任务");r.setProtectedTaskIds(pinned.stream().map(Task::getId).toList());r.setUseAi(false);
  optional.sort(Comparator.comparingInt(t->{var m=metadata.apply(t);return m==null||m.knowledgeId()==null?Integer.MAX_VALUE:rank.getOrDefault(m.knowledgeId(),Integer.MAX_VALUE);}));
  var selected=new ArrayList<Item>();var changes=new ArrayList<TaskChange>();int remaining=r.getAvailableMinutes()-mandatory;
  for(var t:pinned){var old=metadata.apply(t);selected.add(item(t,old,priority.apply(t),costs.get(t.getId()),"保留锁定/定时/截止任务，原记录不修改"));changes.add(new TaskChange(t.getId(),"KEEP",t.getScheduledDate(),t.getScheduledDate(),costs.get(t.getId()),costs.get(t.getId()),"锁定或截止约束"));}
  for(var t:optional){var old=metadata.apply(t);int cost=costs.get(t.getId()),before=minutes(t,old);String reason=old!=null&&old.knowledgeId()!=null&&reasons.containsKey(old.knowledgeId())?"依据当前学习记录："+reasons.get(old.knowledgeId()):"无明确知识映射，沿用原任务顺序，不推断薄弱";
   if(remaining<1){LocalDate next=r.getDate().plusDays(1);if(t.getDueDate()!=null&&next.isAfter(t.getDueDate()))throw new BusinessException(409,"延期会超过真实截止日期，未生成可应用方案");changes.add(new TaskChange(t.getId(),"DEFER",t.getScheduledDate(),next,before,before,reason+"；今日预算不足，延期至下一日"));continue;}
   int assigned=Math.min(cost,remaining);remaining-=assigned;selected.add(item(t,old,priority.apply(t),assigned,reason));changes.add(new TaskChange(t.getId(),assigned<before?"SHORTEN":"REORDER",t.getScheduledDate(),r.getDate(),before,assigned,reason+(assigned<before?"；本次只安排部分时间，不表示内容已完成":"")));
  }
  warnings.add("只调整预览中的既有任务，不创建新任务；锁定/定时/已到期记录保持不变；部分时间安排不代表完成。确认前无日程写入。");return new Changes(List.copyOf(selected),List.copyOf(changes),List.copyOf(warnings));
 }
 private Item item(Task t,Item old,String priority,int cost,String reason){return new Item("task:"+t.getId(),t.getTitle(),old==null?"THEORY":old.type(),cost,priority,old==null?"TOOL":old.resourceType(),old==null?null:old.resourceId(),old==null?null:old.pathId(),old==null?null:old.knowledgeId(),reason,old==null?"按任务说明手动完成；不产生掌握证明":old.completionCondition(),t.getId(),"TASK",t.getStatus());}
 public void validateExact(List<Item> original,List<Item> selected){if(original.size()!=selected.size())throw new BusinessException(400,"智能重排清单不能移除任务，请调整预算或锁定后重新预览");for(int i=0;i<original.size();i++){var a=original.get(i);var b=selected.get(i);if(!a.key().equals(b.key())||!a.title().equals(b.title())||a.estimatedMinutes()!=b.estimatedMinutes()||!a.priority().equals(b.priority()))throw new BusinessException(400,"请通过重新预览修改智能重排，不接受绕过保护的清单变更");}}
 public int freeOrder(long user,Request r,int start){Set<Integer> fixed=new HashSet<>(sql.queryForList("SELECT sort_order FROM task WHERE user_id=? AND deleted=0 AND scheduled_date<=? AND (status=1 OR id IN ("+(r.getProtectedTaskIds().isEmpty()?"-1":String.join(",",r.getProtectedTaskIds().stream().map(String::valueOf).toList()))+")) AND sort_order IS NOT NULL",Integer.class,user,r.getDate()));while(fixed.contains(start))start++;return start;}
 public void deferred(long user,Request r,List<TaskChange> changes,Map<String,String> revisions,Function<Task,String> revision,Function<Task,Item> metadata,List<TaskRef> result){for(var change:changes){if(!"DEFER".equals(change.kind()))continue;var t=tasks.lockOwned(change.taskId(),user);if(t==null)throw new BusinessException(404,"延期任务不存在");if(!Objects.equals(revisions.get("task:"+t.getId()),revision.apply(t))||t.getStatus()!=0||protectedTask(t,r))throw new BusinessException(409,"延期任务已变化，请重新预览");var m=metadata.apply(t);if(m!=null)context.validateResource(m,user);if(t.getDueDate()!=null&&change.newDate().isAfter(t.getDueDate()))throw new BusinessException(409,"不能延期超过截止日期");var dto=new TaskDTO();dto.setScheduledDate(change.newDate());taskService.updateTask(user,t.getId(),dto);guard.moveTask(user,t.getId(),change.newDate());result.add(new TaskRef(t.getId(),"TASK",t.getTitle(),t.getStatus()));}}
}
